export default async function settingsReview(review) {
  await review.waitFor('window.__modelReview?.ready === true');
  const editDialog = 'dialog[open][data-model-dialog="edit"]';
  const connection = `${editDialog} [data-field="provider.baseUrl"]`;
  const credentialInput = `${editDialog} .pd-model-settings-credentials input[type=password]`;
  const savedCalls = 'window.__modelReview.calls.filter(c=>c.name==="saveCustomProvider")';
  const setRange = async (selector, value) => {
    await review.evaluate(`(() => {const e=document.querySelector(${JSON.stringify(selector)});Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(e,${JSON.stringify(String(value))});e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));})()`);
    await review.settle();
  };
  await review.click('.pd-settings-entry');
  await review.clickText('.pd-settings-nav button', '模型管理');
  await review.click('[data-provider="review-gateway"]');
  await review.click('[data-action="edit-provider"]');
  await review.waitFor(`Boolean(document.querySelector(${JSON.stringify(connection)}))`);
  await review.fill(connection, 'https://draft.example.invalid/v1');
  await review.fill(credentialInput, 'public-test-draft-key');
  await review.click(`${editDialog} .pd-model-dialog-header button`);
  await review.waitFor('Boolean(document.querySelector("dialog[open][data-model-dialog=confirm]"))');
  await review.assert('Boolean(document.querySelector("[data-action=save-model-draft-and-leave]"))', 'Closing the provider settings dialog offers save, discard, and continue editing');
  await review.evaluate('window.__modelReview.failures.saveCustomProvider="Deliberate provider save failure"');
  await review.click('[data-action="save-model-draft-and-leave"]');
  await review.waitFor('Boolean(document.querySelector("dialog[open][data-model-dialog=confirm] [role=alert]"))');
  await review.assert(`document.querySelector(${JSON.stringify(connection)}).value === 'https://draft.example.invalid/v1' && document.querySelector(${JSON.stringify(credentialInput)}).value==='public-test-draft-key'`, 'Failed save keeps connection and credential drafts');
  await review.clickText('dialog[open][data-model-dialog=confirm] button', '继续编辑');
  await review.evaluate('delete window.__modelReview.failures.saveCustomProvider');
  await review.click(`${editDialog} .pd-model-dialog-header button`);
  await review.waitFor('Boolean(document.querySelector("dialog[open][data-model-dialog=confirm]"))');
  await review.click('[data-action="save-model-draft-and-leave"]');
  await review.waitFor('document.querySelector("dialog[open].pd-model-dialog") === null');
  await review.assert(`window.__modelReview.providers.find(p=>p.provider==='review-gateway').baseUrl==='https://draft.example.invalid/v1' && window.__modelReview.calls.some(c=>c.name==='setProviderApiKey'&&c.args[0]==='review-gateway')`, 'Save-and-leave saves all changed configuration parts');
  await review.click('[data-provider="review-gateway"]');
  await review.click('[data-action="edit-provider"]');
  await review.waitFor(`Boolean(document.querySelector(${JSON.stringify(connection)}))`);
  await review.fill(connection, 'https://second.example.invalid/v1');
  await review.click(`${editDialog} .pd-model-dialog-header button`);
  await review.waitFor('Boolean(document.querySelector("dialog[open][data-model-dialog=confirm]"))');
  await review.click('[data-action="save-model-draft-and-leave"]');
  await review.waitFor('document.querySelector("dialog[open].pd-model-dialog") === null');
  await review.assert(`window.__modelReview.providers.find(p=>p.provider==='review-gateway').baseUrl==='https://second.example.invalid/v1'`, 'Saving the provider settings draft persists the connection');

  for (const [width, size, theme] of [[1440,12,'深色'],[900,13,'浅色'],[1440,16,'浅色'],[680,20,'深色']]) {
    await review.viewport(width,1000);
    await review.clickText('.pd-settings-nav button','外观');
    await setRange('[data-setting="font"] input',size);
    await review.clickText('.pd-appearance-choice',theme);
    await setRange('#pd-code-font',18);
    await setRange('#pd-command-font',22);
    await review.assert(`document.documentElement.style.getPropertyValue('--pd-ui-font-size')==='${size}px' && document.documentElement.style.getPropertyValue('--pd-code-font-size')==='18px' && document.documentElement.style.getPropertyValue('--pd-command-font-size')==='22px'`, `Independent font preferences at ${size}px`);
    await review.assert('document.documentElement.scrollWidth<=innerWidth', `No page overflow at ${width}px / ${size}px`);
    await review.evaluate('document.querySelector("[data-setting=code-font]").scrollIntoView({block:"center"})');
    await review.screenshot(`settings-fonts-${width}-${size}`);
  }
  await review.reducedMotion(true);
  await review.viewport(900,1000);
  await setRange('[data-setting="font"] input',13);
  await review.clickText('.pd-settings-nav button','常规');
  await review.clickText('.pd-language-options button','English');
  await review.screenshot('settings-general-english');
  await review.click('.pd-settings-header > button');
  await review.evaluate(`(() => { const fixture=window.__modelReview; fixture.editorAttempts=[]; window.piDesktop.openWorkspaceInVsCode=async(cwd)=>{fixture.editorAttempts.push(cwd);if(fixture.editorAttempts.length===1)throw new Error('Editor unavailable for this test');};})()`);
  await review.click('.pd-chat-header-more');
  await review.clickText('.pd-sidebar-popover button','Open in VS Code');
  await review.waitFor('Boolean(document.querySelector(".pd-operation-notice.is-error"))');
  await review.assert('!document.querySelector(".pd-sidebar-popover")', 'Operation failure remains after its menu closes');
  // A one-line failure reason shows directly under the title; no extra disclosure is needed.
  await review.assert('document.querySelector(".pd-operation-notice-reason")?.textContent.includes("Editor unavailable for this test") && document.querySelector(".pd-operation-notice strong")?.textContent.endsWith("failed") && !document.querySelector(".pd-operation-notice summary")', 'Operation failures state what failed and why without opening details');
  await review.screenshot('operation-error-details');
  await review.clickText('.pd-operation-notice button','Retry');
  await review.waitFor('!document.querySelector(".pd-operation-notice")');
  await review.assert('window.__modelReview.editorAttempts.length===2 && window.__modelReview.editorAttempts[0]===window.__modelReview.editorAttempts[1]', 'Retry preserves the original workspace target');
  await review.click('.pd-composer-model-trigger');
  await review.click('.pd-composer-provider-list [data-provider="review-gateway"]');
  await review.assert('document.querySelectorAll(".pd-model-capabilities").length===2 && document.querySelector("[data-model-id=review-fast]").textContent.includes("Text only")', 'Model picker displays real image and reasoning capabilities');
  await review.click('.pd-model-image-filter input');
  await review.assert('!document.querySelector(".pd-composer-picker-model[data-model-id=review-fast]") && Boolean(document.querySelector(".pd-composer-picker-model[data-model-id=review-reasoner]"))', 'Image filter excludes incompatible models without selecting another model');
  await review.assert('window.__modelReview.snapshot.model==="gpt-review"', 'Compatibility filtering never changes the selected model');
  await review.screenshot('model-image-capabilities');
  // 供应商模型多了以后，列表必须滚动，而不是把每行压扁——压扁会让行内文字压到下一行。
  await review.click('.pd-model-image-filter input');
  await review.key('Escape');
  await review.evaluate(`(() => { const provider = window.__modelReview.providers.find(item => item.provider === 'review-gateway'); for (let index = 0; index < 6; index++) provider.models.push({ provider: 'review-gateway', id: 'crowded-' + index, name: '挤压回归模型 ' + index, reasoning: true, input: ['text'], contextWindow: 128000, maxTokens: 8192 }); return provider.models.length; })()`);
  await review.click('.pd-composer-model-trigger');
  await review.click('.pd-composer-provider-list [data-provider="review-gateway"]');
  await review.waitFor('document.querySelectorAll(".pd-composer-picker-model").length > 5');
  await review.assert('(() => { const list = document.querySelector(".pd-composer-provider-models .pd-composer-picker-list"); return list.scrollHeight > list.clientHeight; })()', 'Crowded model list scrolls instead of shrinking its rows');
  await review.assert('[...document.querySelectorAll(".pd-composer-picker-model")].every(row => { const content = row.querySelector(":scope > span"); return content.getBoundingClientRect().bottom <= row.getBoundingClientRect().bottom + 0.5; })', 'Model rows keep full height so their text never paints over the next row');
  await review.screenshot('model-picker-crowded-list');
  await review.key('Escape');
  await review.evaluate(`(() => { const fixture=window.__modelReview; fixture.installAttempts=0; window.piDesktop.installUpdate=async()=>{fixture.installAttempts++;if(fixture.installAttempts===1)throw new Error('Update unavailable for this test');return new Promise(resolve=>{fixture.finishInstallation=resolve;});};fixture.emit('onUpdateStateChanged',{phase:'available',currentVersion:'0.1.5',availableVersion:'0.1.6'});})()`);
  await review.click('.pd-update-notice-primary');
  await review.waitFor('Boolean(document.querySelector(".pd-operation-notice.is-error"))');
  await review.click('.pd-sidebar-collapse');
  await review.assert('Boolean(document.querySelector(".pd-sidebar.is-collapsed")) && !document.querySelector(".pd-operation-notice").closest(".pd-sidebar")', 'Sidebar failure remains accessible after collapsing the sidebar');
  await review.evaluate(`(() => {const retry=[...document.querySelectorAll('.pd-operation-notice button')].find(button=>button.textContent==='Retry');retry.click();retry.click();})()`);
  await review.waitFor('Boolean(window.__modelReview.finishInstallation)');
  await review.assert('window.__modelReview.installAttempts===2 && document.querySelector(".pd-operation-notice").getAttribute("aria-busy")==="true"', 'Repeated notice retry starts only one installation and exposes pending state');
  await review.evaluate('window.__modelReview.finishInstallation()');
  await review.waitFor('!document.querySelector(".pd-operation-notice")');
  await review.record('save-calls',`${savedCalls}.map(c=>({provider:c.args[0].provider,baseUrl:c.args[0].baseUrl}))`);
}
